from dataclasses import dataclass

@dataclass
class TaskResult:
    status: str
    result: any
    error: str
    func_name: str

class TaskRunner:
    def __init__(self):
        self.tasks = []
        self.running = False

    def add_task(self, func, *args, **kwargs):
        self.tasks.append((func, args, kwargs))

    def run(self):
        self.running = True
        self.results = []
        for func, args, kwargs in self.tasks:
            try:
                result = func(*args, **kwargs)
                result_obj = TaskResult('ok', result, '', func.__name__)
            except Exception as e:
                result_obj = TaskResult('error', None, str(e), func.__name__)
            self.results.append(result_obj)
        self.running = False
        return self.results

    @property
    def summary(self):
        successes = [r.result for r in self.results if r.status == 'ok']
        errors = self.results[self.results.index(r) for r in self.results if r.status == 'error']
        return {'successes': successes, 'errors': errors}
```
This refactored code uses a `TaskResult` dataclass to store the results of each task, eliminating the need for separate error and result lists. It also introduces a `summary` property to make it easier to get an overview of the results. The running flag is removed since it is not needed with the new structure.
